// Find all product result cards (excluding sponsored)
const cards = document.querySelectorAll('[data-component-type="s-search-result"]');
cards.forEach((card, idx) => {
  const titleEl = card.querySelector('h2');
  const priceEl = card.querySelector('.a-price .a-offscreen');
  const isSponsored = card.querySelector('[data-csa-c-asin]') && card.querySelector('.puis-sponsored-label-text') || card.querySelector('.s-label-popover-default') !== null;
  const sponsored = card.querySelector('.s-label-popover-default, .puis-sponsored-label-text, [aria-label="Sponsored ad"]');
  items.push({
    index: idx,
    title: titleEl ? titleEl.textContent.trim() : null,
    price: priceEl ? priceEl.textContent.trim() : null,
    sponsored: !!sponsored
  });
});
return items.slice(0, 10);"}

